function joinGang(n){S.gang=n;S.rep+=1;advance(2);log(`You joined the ${n}. A new chapter begins.`);toast(`Welcome to ${n}.`);render()}function leaveGang(){S.gang='Independent';advance(1);log('You stepped away from crew life.');render()}function turfAction(){advance(3);S.rep+=2;S.skills.Streetwise=Math.min(10,S.skills.Streetwise+1);if(Math.random()<.35){S.heat=Math.min(5,S.heat+1);toast('A tense neighborhood clash drew attention.')}else toast('Your crew strengthened its local ties.');log(`${S.gang} built influence in ${districts[S.district].name}.`);checkHeat();render()}
function earn(n,msg,skill){advance(2);S.cash+=n;S.needs.Energy=Math.max(0,S.needs.Energy-9);S.skills[skill]=Math.min(10,S.skills[skill]+(Math.random()<.42?1:0));S.rep++;log(msg);toast(`Earned ${money(n)}`);render()}function career(){openDialog('Career desk','Build a reliable path. Career roles add recurring income and small bonuses as your skills grow.',[['Tech support trainee','$95 per shift · Social skill',()=>getJob('Tech support trainee')],['Kitchen prep',' $72 per shift · Fitness skill',()=>getJob('Kitchen prep')],['Community aide','$78 per shift · Social skill',()=>getJob('Community aide')]])}function getJob(j){S.job=j;S.rep++;toast(`You started as ${j}.`);log(`A new opportunity: ${j}.`);advance(1);render()}
function spend(n,msg){if(S.cash<n){toast('Not enough cash');return}S.cash-=n;advance(1);log(msg);render()}function buyFood(){if(S.cash<9){toast('Not enough cash for a meal');return}S.cash-=9;S.needs.Food=Math.min(100,S.needs.Food+38);S.needs.Mood=Math.min(100,S.needs.Mood+5);advance(1);toast('A good meal hits the spot.');log('You grabbed a meal.');render()}function buyWater(){if(S.cash<3){toast('Not enough cash');return}S.cash-=3;S.needs.Water=Math.min(100,S.needs.Water+44);advance(1);render()}function rentRoom(label){if(S.cash<120){toast('You need $120 for the deposit');return}S.cash-=120;S.home=label;advance(1);S.needs.Mood=Math.min(100,S.needs.Mood+14);log(`You rented a room at ${label}. A key of your own.`);toast('A place of your own.');render()}function payRent(){let r=districts[S.district].rent;if(S.cash<r){toast('You are short on rent. Find some work.');return}S.cash-=r;advance(1);log(`Paid ${money(r)} weekly rent.`);toast('Rent paid.');render()}function restAction(){let amount=S.home==='Couch surfing'?36:66;S.needs.Energy=Math.min(100,S.needs.Energy+amount);S.needs.Mood=Math.min(100,S.needs.Mood+9);S.hour=7;S.min=0;advance(8);toast(S.home==='Couch surfing'?'You got a few hours on the couch.':'You woke up feeling rested.');log('You got some sleep.');render()}
function hangout(){advance(2);S.needs.Mood=Math.min(100,S.needs.Mood+18);S.skills.Social=Math.min(10,S.skills.Social+(Math.random()<.5?1:0));S.rep++;log('You spent time with people around the neighborhood.');toast('A little connection goes a long way.');render()}function exercise(){advance(1);S.needs.Energy=Math.max(0,S.needs.Energy-12);S.needs.Mood=Math.min(100,S.needs.Mood+7);S.skills.Fitness=Math.min(10,S.skills.Fitness+1);toast('Fitness improved.');render()}function travel(i){if(i===S.district){toast('You are already here');return}if(S.cash<12){toast('You need $12 for a transit fare');return}S.cash-=12;S.district=i;S.x=610;S.y=430;advance(2);document.querySelector('#districts').querySelectorAll('button').forEach((b,j)=>b.classList.toggle('active',i===j));log(`You rode transit to ${districts[i].name}.`);toast(`Welcome to ${districts[i].name}`);render()}
function advance(hours){S.hour+=hours;while(S.hour>=24){S.hour-=24;S.day++;S.needs.Food=Math.max(0,S.needs.Food-8);S.needs.Water=Math.max(0,S.needs.Water-12);S.needs.Hygiene=Math.max(0,S.needs.Hygiene-6);S.needs.Mood=Math.max(0,S.needs.Mood-3);if(S.day>28){S.day=1;S.month++;if(S.month>12){S.month=1;S.year++;S.age++;log(`Happy birthday! You are now ${S.age}.`)}}if((S.day-1)%7===0){if(S.home!=='Couch surfing'){let rent=districts[S.district].rent;if(S.cash>=rent){S.cash-=rent;log(`Weekly rent of ${money(rent)} paid automatically.`)}else{S.home='Couch surfing';S.needs.Mood=Math.max(0,S.needs.Mood-16);log('You missed rent and lost your room.')}}}}let mins=S.min+hours*60;S.hour=(S.hour+Math.floor(mins/60))%24;S.min=mins%60;render()}
function contextAction(){if(near>=0){interact();return}if(S.gang!=='Independent'){turfAction();return}openDialog('A choice in the street','Keep it abstract: quick, risky street hustles can raise heat and have consequences. No real-world tactics—just a branching RPG choice.',[['Take a small opportunistic hustle','$35 · 35% chance of added heat',()=>hustle(35,.35)],['Try a high-risk score','$90 · 65% chance of added heat',()=>hustle(90,.65)],['Walk away','Stay out of trouble',()=>toast('You kept moving.')]])}
function hustle(pay,risk){advance(2);S.skills.Streetwise=Math.min(10,S.skills.Streetwise+(Math.random()<.4?1:0));S.rep++;if(Math.random()<risk){S.heat=Math.min(5,S.heat+1);S.cash+=Math.floor(pay*.4);log('A street hustle went sideways. You escaped with less and drew attention.');toast('The risk caught up with you.');checkHeat()}else{S.cash+=pay;log('A risky street hustle paid off.');toast(`You got ${money(pay)}.`)}render()}
