const sleep = ms => new Promise(r => setTimeout(r, ms));
const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = targets.find(t => t.type === 'page');
if (!page) throw new Error('No Chromium page target');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
const events = [];
ws.onmessage = e => {
  const msg = JSON.parse(e.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  else events.push(msg);
};
function call(method, params = {}) {
  const n = ++id;
  return new Promise((resolve, reject) => {
    pending.set(n, msg => msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result));
    ws.send(JSON.stringify({id:n, method, params}));
  });
}
async function evalJS(expression) {
  const result = await call('Runtime.evaluate', {expression, awaitPromise:true, returnByValue:true, userGesture:true});
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.text + ' :: ' + (result.exceptionDetails.exception?.description || ''));
  return result.result.value;
}
await call('Runtime.enable');
await call('Page.enable');
await sleep(800);
const report = {};
report.initial = await evalJS(`({title:document.title, clock:document.querySelector('#clock').textContent, canvas:!!document.querySelector('#world').getContext('2d'), needs:document.querySelectorAll('.need').length, district:document.querySelector('#districtName').textContent, saved:localStorage.getItem('baybound-save')})`);
await evalJS(`S.x=agents[1].x;S.y=agents[1].y;updateNear();interact()`);
