await evalJS(`S.x=890;S.y=645;updateNear();interact()`);
report.hubDialog = await evalJS(`({title:document.querySelector('#modalTitle').textContent, choices:document.querySelectorAll('.choice').length})`);
await evalJS(`document.querySelector('.choice').click()`);
report.missionAccepted = await evalJS(`({mission:S.mission, objective:document.querySelector('#objective').innerText, modal:document.querySelector('#dialog').classList.contains('open')})`);
await evalJS(`S.x=385;S.y=620;updateNear();interact()`);
report.parkDialog = await evalJS(`({title:document.querySelector('#modalTitle').textContent, delivery:[...document.querySelectorAll('.choice b')].some(x=>x.textContent.includes('Deliver pantry'))})`);
