function buildingBounds(){let out=[];for(let bx=15;bx<1500;bx+=300)for(let bz=12;bz<900;bz+=280){let x=bx+95,z=bz+88;if(x<1460)out.push({x,z,w:166,d:170})}return out}
function isBlocked(x,y,r=12){if(x<40+r||x>1460-r||y<40+r||y>860-r)return true;for(let b of buildingBounds()){let px=Math.max(b.x,Math.min(x,b.x+b.w)),py=Math.max(b.z,Math.min(y,b.z+b.d));if(Math.hypot(x-px,y-py)<r)return true}return false}
function nearestSafePoint(x,y){let best={x:340,y:440},distance=Infinity;for(let sx of [40,340,640,940,1240,1440])for(let sy of [40,320,600,840])if(!isBlocked(sx,sy)){let d=Math.hypot(sx-x,sy-y);if(d<distance){distance=d;best={x:sx,y:sy}}}return best}
function moveActor(actor,x,y,r=12){x=Math.max(40+r,Math.min(1460-r,x));y=Math.max(40+r,Math.min(860-r,y));if(!isBlocked(x,actor.y,r))actor.x=x;if(!isBlocked(actor.x,y,r))actor.y=y}
